# Generated by test-lab — blind adversarial evaluation
"""Focused frame-evidence guards."""

from datetime import datetime, timezone

import pytest
from pydantic import ValidationError

from live_evidence.frame_evidence import (
    content_sha256,
    frame_ref,
    stable_frame_id,
    validate_card_frame_evidence,
)
from live_evidence.models import (
    CardStatus,
    EvidenceCard,
    EvidenceSource,
    FrameChangeReason,
    FrameEvidence,
    FrameRetention,
    Freshness,
    RetrievalLane,
)


CAPTURED_AT = datetime(2026, 8, 25, 14, 0, 0, tzinfo=timezone.utc)


def _frame(content: bytes = b"diagram-frame") -> FrameEvidence:
    digest = content_sha256(content)
    return FrameEvidence(
        frame_id=stable_frame_id(
            source="browser-tab:coding-screen",
            captured_at=CAPTURED_AT,
            content_sha256=digest,
        ),
        captured_at=CAPTURED_AT,
        source="browser-tab:coding-screen",
        content_sha256=digest,
        change_reason=FrameChangeReason.VISUAL_CHANGE,
        retention=FrameRetention.SESSION_ONLY,
        path="/tmp/live-evidence-frame.png",
        transcript_event_ids=["event-visual-0001"],
        observations=["whiteboard shows Redis cache invalidation diagram"],
    )


def _card(frame_refs: list[str] | None = None) -> EvidenceCard:
    source = EvidenceSource(
        lane=RetrievalLane.RIPGREP,
        label="repo evidence",
        excerpt="The cache invalidation code updates dependent keys.",
        score=0.9,
        freshness=Freshness.CURRENT,
        path="/tmp/repo/cache.py",
        repository="demo",
    )
    return EvidenceCard(
        query="Which part of the diagram maps to cache invalidation?",
        thread="visual interview",
        talking_point="The invalidation node maps to dependent key updates.",
        proof="repo evidence plus exact screen frame",
        qualifier="bounded to the cited frame",
        confidence=0.85,
        status=CardStatus.SUPPORTED,
        sources=[source],
        frame_refs=frame_refs or [],
        lanes=[RetrievalLane.RIPGREP],
        question_id="question-visual-0001",
        question_revision=1,
    )


def test_frame_evidence_requires_timezone_and_sha256() -> None:
    with pytest.raises(ValidationError):
        FrameEvidence(
            frame_id="frame-bad",
            captured_at=datetime(2026, 8, 25, 14, 0, 0),
            source="browser-tab:demo",
            content_sha256="not-a-sha",
            change_reason=FrameChangeReason.VISUAL_CHANGE,
        )


def test_visual_dependent_card_accepts_exact_frame_ref() -> None:
    frame = _frame()
    decision = validate_card_frame_evidence(
        _card([frame_ref(frame)]),
        frames=[frame],
        visual_required=True,
    )

    assert decision.ok is True
    assert decision.reason_codes == ["visual_frame_provenance_resolved"]
    assert decision.frame_refs == [frame_ref(frame)]


def test_visual_dependent_card_holds_without_frame_ref() -> None:
    decision = validate_card_frame_evidence(
        _card(),
        frames=[_frame()],
        visual_required=True,
    )

    assert decision.ok is False
    assert decision.reason_codes == ["visual_card_missing_frame_ref"]


def test_visual_dependent_card_rejects_nearby_irrelevant_frame() -> None:
    correct = _frame(b"correct-frame")
    nearby_irrelevant = _frame(b"nearby-but-wrong-frame")
    decision = validate_card_frame_evidence(
        _card([frame_ref(correct)]),
        frames=[nearby_irrelevant],
        visual_required=True,
    )

    assert decision.ok is False
    assert decision.reason_codes == ["unresolved_frame_provenance"]
    assert decision.frame_refs == [frame_ref(correct)]


def test_audio_only_card_does_not_require_frame() -> None:
    decision = validate_card_frame_evidence(
        _card(),
        frames=[],
        visual_required=False,
    )

    assert decision.ok is True
    assert decision.reason_codes == ["audio_only_no_frame_required"]
